#define Pi 3.141592653

// 帮助说明文档 https://zhuanlan.zhihu.com/p/466372256
// 计算多边形形状的函数
float Polygon(vec2 uv, float r, int N) {
    // 计算向量 uv 与 y 轴正方向的夹角
    float angle = atan(uv.x, uv.y); 
    // 计算每个扇区的角度
    float theta = 2.0 * Pi / float(N); 
    // 计算每个扇区的一半角度
    float helfTheta = theta / 2.0;

    // 计算 angle 与最近扇区中心角度的差值
    float dangle = mod(angle, theta) - helfTheta;
    // 计算点到多边形边界的距离
    float d = cos(dangle) * length(uv);
    // 使用 smoothstep 函数平滑地在 0 和 1 之间插值，生成多边形形状
    return smoothstep(0., 0.01, d - r);
}

// 主函数，用于设置每个像素的颜色
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 将屏幕坐标转换为归一化的坐标，范围在 [-1, 1] 之间
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.y, iResolution.x);

    // 初始化颜色为白色
    vec3 color = vec3(1.0);
    // 使用 Polygon 函数生成多边形形状，并将颜色混合为黑色
    color = mix(color, vec3(0.), Polygon(uv, 0.3, 3));
    // 设置最终的像素颜色
    fragColor = vec4(color, 1.0);
}
